{
  "гриб": "Мухомор вонючий (Amanita virosa)",
  "состав": [
    {
      "вещество": "α-Аманитин (α-amanitin)",
      "содержание": "1–2 % от сухого веса",
      "влияние": "Необратимо ингибирует РНК-полимеразу II, вызывая гибкость гепатоцитов, нефроцитов и клеток ЖКТ, что приводит к печёночной и почечной недостаточности."
    },
    {
      "вещество": "β-Аманитин (β-amanitin)",
      "содержание": "0,1–0,5 % от сухого веса",
      "влияние": "Ингибирует РНК-полимеразу II с меньшей аффинностью, чем α-аманитин, усугубляя цитотоксическое действие на печень и почки."
    },
    {
      "вещество": "α-Фаллотоксин (α-phallotoxin)",
      "содержание": "0,1–0,5 % от сухого веса",
      "влияние": "Диссоциирует актиновые микроволокна, нарушая цитоскелет и деление клеток печени и почек."
    },
    {
      "вещество": "β-Фаллотоксин (β-phallotoxin)",
      "содержание": "неизвестно",
      "влияние": "Обладает более слабым действием на актиновый цитоскелет, чем α-фаллотоксин."
    },
    {
      "вещество": "ε-Аманитин (ε-amanitin)",
      "содержание": "неизвестно",
      "влияние": "Слабый ингибитор РНК-полимеразы II, вносит незначительный вклад в общую аманитоксическую токсичность."
    },
    {
      "вещество": "Виренин (virenin)",
      "содержание": "неизвестно",
      "влияние": "Нетоксичный циклопептид, не оказывает значимого физиологического действия на человека."
    }
  ]
}
